function Get-WingetUpgrades {
        $raw = winget upgrade --include-unknown 2>&1 | Out-String
        $lines = $raw -split "`r?`n"
        $headerLine = $null
        $idCol = -1
        $verCol = -1
        $availCol = -1
        $srcCol = -1

        for ($i = 0; $i -lt $lines.Count; $i++) {
            if ($lines[$i] -match '^-{20,}') {
                $headerLine = $lines[$i - 1]
                break
            }
        }

        if (-not $headerLine -or $headerLine -notmatch 'Id') {
            return @()
        }

        $idCol = $headerLine.IndexOf('Id')
        $verCol = $headerLine.IndexOf('Version')
        $availCol = $headerLine.IndexOf('Available')
        $srcCol = $headerLine.IndexOf('Source')

        if ($idCol -lt 0 -or $verCol -lt 0 -or $availCol -lt 0) {
            return @()
        }

        $packages = @()
        $dataSection = $false
        foreach ($line in $lines) {
            if ($line -match '^-{20,}') {
                $dataSection = $true
                continue
            }

            if (-not $dataSection) { continue }
            if ($line -match '^\d+ upgrades? available') { break }
            if ([string]::IsNullOrWhiteSpace($line)) { continue }

            $padded = if ($srcCol -gt 0) {
                $line.PadRight([Math]::Max($line.Length, $srcCol + 1))
            } else {
                $line
            }

            if ($padded.Length -lt $availCol) { continue }

            $name = $padded.Substring(0, $idCol).Trim()
            $pkgId = $padded.Substring($idCol, $verCol - $idCol).Trim()
            $current = $padded.Substring($verCol, $availCol - $verCol).Trim()
            $available = if ($srcCol -gt $availCol) {
                $padded.Substring($availCol, $srcCol - $availCol).Trim()
            } else {
                $padded.Substring($availCol).Trim()
            }

            if ($name -and $pkgId -and $current -and $available) {
                $packages += [pscustomobject]@{
                    Name = $name
                    Id = $pkgId
                    Current = $current
                    Available = $available
                }
            }
        }

        return $packages
    }

if ($MyInvocation.InvocationName -ne '.') {
